package io.github.jackotom.hongguo.android;

import java.io.*;
import java.lang.reflect.*;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.json.*;

/** Selected-1080p CDN DNS recovery using real plans/cache and injected offline transfers. */
public final class Playback1080RecoveryTest {
    static final String SID="980001",VID="980009",QUALITY="1080p",KEY="00112233445566778899aabbccddeeff",FRESH_KEY="ffeeddccbbaa99887766554433221100";
    static int passed,failed,checks;static MainActivity host;static File directory;static final List<JSONArray> calls=new ArrayList<>();
    interface Checked{void run()throws Exception;}
    static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static Exception rejects(Checked task,String message)throws Exception{try{task.run();}catch(Exception expected){checks++;return expected;}throw new AssertionError(message);}
    static void group(String name,Checked task){try{reset();task.run();passed++;System.out.println("PASS "+name);}catch(Throwable error){failed++;System.out.println("FAIL "+name+": "+error.getClass().getSimpleName()+" "+error.getMessage());}finally{Thread.interrupted();}}
    @SuppressWarnings("unchecked") static void reset()throws Exception{NetworkGuard.reset();calls.clear();Field field=PlaybackSources.class.getDeclaredField("plans");field.setAccessible(true);Map<String,PlaybackSources.Plan> plans=(Map<String,PlaybackSources.Plan>)field.get(null);synchronized(plans){plans.clear();}reply(model("unused"));}
    static JSONObject model(String name)throws Exception{return new JSONObject().put("url","https://cdn.qznovelvod.com/fixture-1080-"+name+".mp4").put("source","app").put("seriesId",SID).put("vid",VID).put("contentKey",KEY).put("userAgent","fixture old agent").put("referer","https://novelquickapp.com/").put("requestedQuality",QUALITY).put("width",1920).put("height",1080);}
    static JSONObject candidates(String prefix,int count)throws Exception{JSONObject primary=model(prefix+"-0");JSONArray variants=new JSONArray();for(int i=1;i<count;i++)variants.put(model(prefix+"-"+i));return primary.put("variants",variants);}
    static List<String> urls(JSONObject plan)throws Exception{List<String> urls=new ArrayList<>();urls.add(plan.getString("url"));JSONArray variants=plan.optJSONArray("variants");if(variants!=null)for(int i=0;i<variants.length();i++)urls.add(variants.getJSONObject(i).getString("url"));return urls;}
    static JSONArray arguments(String script)throws Exception{return new JSONArray("["+script.substring(script.lastIndexOf('(')+1,script.length()-1)+"]");}
    static JSONObject envelope(JSONArray a)throws Exception{return new JSONObject().put("requestId",a.getString(0)).put("seriesId",a.getString(1)).put("vid",a.getString(2)).put("requestedQuality",a.getString(3));}
    static void reply(JSONObject info){host.callback=script->{try{JSONArray a=arguments(script);calls.add(a);PlaybackSources.result(envelope(a).put("playInfo",info));}catch(Exception error){throw new RuntimeException(error);}};}
    static void exactRequest()throws Exception{for(JSONArray request:calls)check(request.getString(1).equals(SID)&&request.getString(2).equals(VID)&&request.getString(3).equals(QUALITY),"fresh model stays on exact episode and selected 1080p");}
    static byte[] key(String hex){byte[] key=new byte[16];for(int i=0;i<16;i++)key[i]=(byte)Integer.parseInt(hex.substring(i*2,i*2+2),16);return key;}
    static File part(String name){return new File(directory,name+".part");}
    static void clean(File target)throws Exception{if(target.exists())check(target.delete(),"fixture successful part removed");}
    static void allCleanStarts(){for(boolean clean:NetworkGuard.cleanAtStart)check(clean,"each candidate starts after prior partial bytes were removed");}
    static void zeroLookup(){check(calls.isEmpty()&&EpisodeResolver.calls==0&&NetworkGuard.heads==0&&AppTransport.heads==0,"fatal/cancelled explicit work does not lookup web/App or HEAD");}
    static void delete(File value){if(value.isDirectory()){File[] files=value.listFiles();if(files!=null)for(File child:files)delete(child);}value.delete();}
    public static void main(String[]unused)throws Exception{
        directory=Files.createTempDirectory("hongguo-1080-recovery-").toFile();host=new MainActivity();PlaybackSources.attach(host);
        try{
            group("typed direct and wrapped DNS failure refresh exact 1080p once with new key headers",()->{for(String failure:new String[]{"dns","wrapped-dns","nested-dns"}){reset();JSONObject old=model("old-"+failure),fresh=model("fresh-"+failure).put("contentKey",FRESH_KEY).put("userAgent","fixture fresh agent");String oldUrl=old.getString("url"),freshUrl=fresh.getString("url");PlaybackSources.Plan original=PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(oldUrl,failure);CencDecryptor.expectedKeys.put(freshUrl,key(FRESH_KEY));reply(fresh);File target=part(failure);long started=System.nanoTime();PlaybackSources.download(oldUrl,target,64,QUALITY);check(calls.size()==1&&NetworkGuard.attempted.equals(Arrays.asList(oldUrl,freshUrl)),"typed DNS obtains exactly one fresh model before successful transfer");check(System.nanoTime()-started>=2_000_000_000L,"fresh DNS lookup waits beyond Android negative address-cache TTL");exactRequest();allCleanStarts();check(NetworkGuard.agents.get(freshUrl).equals("fixture fresh agent")&&NetworkGuard.referers.get(freshUrl).equals("https://novelquickapp.com/"),"fresh candidate uses its own authorized headers");check(CencDecryptor.calls==1&&CencDecryptor.keyMatches.equals(Arrays.asList(true))&&Arrays.equals(Files.readAllBytes(target.toPath()),new byte[]{7,8,9}),"only complete successful fresh candidate decrypts with its own key");check(PlaybackSources.find(oldUrl,QUALITY)==original&&PlaybackSources.find(freshUrl,QUALITY)==null,"refresh remains job local, preserving original quality cache identity");check(NetworkGuard.heads==0&&AppTransport.heads==0&&EpisodeResolver.calls==0,"explicit 1080p does not run HEAD/web fallback");clean(target);}});
            group("old DNS candidates are exhausted in order before a single fresh-model lookup",()->{JSONObject old=candidates("ordered-old",3),fresh=candidates("ordered-new",2);List<String> oldUrls=urls(old),freshUrls=urls(fresh);for(String url:oldUrls)NetworkGuard.outcomes.put(url,"dns");PlaybackSources.register(old,VID,false);host.callback=script->{try{check(NetworkGuard.attempted.equals(oldUrls),"all old candidates precede fresh model request");JSONArray a=arguments(script);calls.add(a);PlaybackSources.result(envelope(a).put("playInfo",fresh));}catch(Exception error){throw new RuntimeException(error);}};File target=part("ordered");PlaybackSources.download(oldUrls.get(0),target,64,QUALITY);List<String> expected=new ArrayList<>(oldUrls);expected.add(freshUrls.get(0));check(NetworkGuard.attempted.equals(expected)&&calls.size()==1,"ordered variants plus one renewed candidate, no episode skip");exactRequest();allCleanStarts();clean(target);});
            group("all DNS failures stay within two rounds eight candidates and clean every failed part",()->{JSONObject old=candidates("limit-old",8),fresh=candidates("limit-new",8);List<String> expected=urls(old);expected.addAll(urls(fresh));for(String url:expected)NetworkGuard.outcomes.put(url,"dns");PlaybackSources.register(old,VID,false);reply(fresh);File target=part("limit");rejects(()->PlaybackSources.download(old.getString("url"),target,64,QUALITY),"exhausted DNS candidates returned media");check(calls.size()==1&&NetworkGuard.attempted.equals(expected)&&NetworkGuard.downloads==16&&!target.exists(),"one model refresh, maximum sixteen transfers, no partial plaintext/ciphertext left");exactRequest();allCleanStarts();});
            group("typed DNS refresh lookup failure does not nest initial lookup retries",()->{JSONObject old=model("lookup-fails");PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(old.getString("url"),"dns");host.callback=script->{try{JSONArray a=arguments(script);calls.add(a);PlaybackSources.result(envelope(a).put("error","fixture fresh DNS lookup failed").put("errorCode","ENOTFOUND"));}catch(Exception error){throw new RuntimeException(error);}};File target=part("lookup-fails");rejects(()->PlaybackSources.download(old.getString("url"),target,64,QUALITY),"failed model lookup returned media");check(calls.size()==1&&NetworkGuard.downloads==1&&!target.exists(),"caller-owned media refresh does not multiply DNS lookup retry owners");exactRequest();});
            group("direct wrapped and already requested cancellation perform zero refresh",()->{for(String failure:new String[]{"interrupt","wrapped-interrupt"}){reset();JSONObject old=model("cancel-"+failure);PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(old.getString("url"),failure);File target=part("cancel-"+failure);rejects(()->PlaybackSources.download(old.getString("url"),target,64,QUALITY),"cancelled transfer succeeded");check(NetworkGuard.downloads==1&&!target.exists(),"cancelled transfer removes its partial file");zeroLookup();Thread.interrupted();}reset();JSONObject old=model("already-cancelled");PlaybackSources.register(old,VID,false);Thread.currentThread().interrupt();File target=part("already-cancelled");rejects(()->PlaybackSources.download(old.getString("url"),target,64,QUALITY),"already cancelled work transferred bytes");check(NetworkGuard.downloads==0&&!target.exists(),"already cancelled work starts no transfer");zeroLookup();Thread.interrupted();});
            group("DNS negative-cache backoff cancels promptly before a fresh model is requested",()->{JSONObject old=model("backoff-cancel");PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(old.getString("url"),"dns");File target=part("backoff-cancel");AtomicReference<Throwable> failure=new AtomicReference<>();boolean[] interrupted={false};Thread worker=new Thread(()->{try{PlaybackSources.download(old.optString("url"),target,64,QUALITY);failure.set(new AssertionError("cancelled backoff returned success"));}catch(Throwable error){failure.set(error);interrupted[0]=Thread.currentThread().isInterrupted();}},"fixture-1080-dns-cancel");worker.start();long limit=System.nanoTime()+1_500_000_000L;while(worker.isAlive()&&worker.getState()!=Thread.State.TIMED_WAITING&&System.nanoTime()<limit)Thread.sleep(2);check(worker.isAlive()&&worker.getState()==Thread.State.TIMED_WAITING,"typed DNS enters bounded negative-cache backoff");worker.interrupt();worker.join(1500);check(!worker.isAlive()&&failure.get() instanceof InterruptedException&&interrupted[0]&&calls.isEmpty()&&NetworkGuard.downloads==1&&!target.exists(),"backoff cancellation returns promptly preserving interrupt and cleaning partial bytes");});
            group("TLS certificate owners and mere DNS error text still never refresh",()->{for(String failure:new String[]{"tls","tls-dns","dns-text","fail"}){reset();JSONObject old=model("fatal-"+failure);PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(old.getString("url"),failure);File target=part("fatal-"+failure);rejects(()->PlaybackSources.download(old.getString("url"),target,64,QUALITY),"fatal transfer produced media");check(NetworkGuard.downloads==1&&!target.exists(),"fatal failure stops with no retained failed bytes: "+failure);zeroLookup();}});
            group("fresh 720p missing-size wrong-episode and bad-variant models cannot publish 1080p cache",()->{
                List<JSONObject> invalid=Arrays.asList(model("low-fresh").put("width",1280).put("height",720),model("unmeasured-fresh").put("height",JSONObject.NULL),model("wrong-episode-fresh").put("vid","980010"),model("bad-variant-fresh").put("variants",new JSONArray().put(model("low-variant").put("height",720))));
                for(int i=0;i<invalid.size();i++){reset();JSONObject old=model("invalid-new-"+i);PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(old.getString("url"),"dns");reply(invalid.get(i));File cacheDirectory=new File(directory,"reject-cache-"+i);PlaybackCachePolicy cache=new PlaybackCachePolicy(cacheDirectory,256,64,(url,target,max)->PlaybackSources.download(url,target,max,QUALITY));rejects(()->cache.fetch(SID,MediaQuality.cacheVid(VID,QUALITY),8,old.getString("url")),"invalid refreshed model published selected 1080p cache");check(calls.size()==1&&NetworkGuard.downloads==1&&cache.find(SID,MediaQuality.cacheVid(VID,QUALITY),8)==null&&cache.status().files==0,"invalid fresh model rejected before fresh transfer/publication");File[] files=cacheDirectory.listFiles();check(files!=null&&files.length==0,"invalid fresh model leaves no .part or published media");exactRequest();}
            });
            group("validated renewed 1080p bytes atomically publish under the original episode quality key",()->{JSONObject old=model("cache-old"),fresh=model("cache-fresh");PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(old.getString("url"),"dns");reply(fresh);File cacheDirectory=new File(directory,"success-cache");PlaybackCachePolicy cache=new PlaybackCachePolicy(cacheDirectory,256,64,(url,target,max)->PlaybackSources.download(url,target,max,QUALITY));String cacheVid=MediaQuality.cacheVid(VID,QUALITY);File result=cache.fetch(SID,cacheVid,8,old.getString("url"));check(result.equals(cache.find(SID,cacheVid,8))&&result.isFile()&&cache.status().files==1,"fresh complete media publishes to original selected-quality episode identity");check(cache.find(SID,VID,8)==null&&cache.find(SID,MediaQuality.cacheVid(VID,"720p"),8)==null,"selected 1080p cache never masquerades as automatic or 720p");for(File file:cacheDirectory.listFiles())check(!file.getName().endsWith(".part"),"successful atomic publication leaves no .part");check(calls.size()==1&&NetworkGuard.downloads==2,"successful cache uses one source refresh and two transfers");exactRequest();});
            System.out.println("PLAYBACK_1080_RECOVERY_"+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" networkRequests=0 deviceTests=not_run");
            if(failed!=0)throw new AssertionError("1080p playback DNS recovery tests failed");
        }finally{PlaybackSources.detach(host);Thread.interrupted();delete(directory);}
    }
}
